-- modify "users" table
ALTER TABLE "users" ALTER COLUMN "password_hash" DROP NOT NULL;
-- create "admin_credential_tokens" table
CREATE TABLE "admin_credential_tokens" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "kind" character varying(16) NOT NULL, "token_hash" character varying(64) NOT NULL, "created_by" bigint NULL, "expires_at" timestamptz NOT NULL, "used_at" timestamptz NULL, "created_at" timestamptz NOT NULL, "user_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "admin_credential_tokens_users_user" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "admin_credential_tokens_kind_check" CHECK ((kind)::text = ANY ((ARRAY['setup'::character varying, 'reset'::character varying])::text[])));
-- create index "admin_credential_tokens_token_hash_key" to table: "admin_credential_tokens"
CREATE UNIQUE INDEX "admin_credential_tokens_token_hash_key" ON "admin_credential_tokens" ("token_hash");
-- create index "admincredentialtoken_user_id_kind" to table: "admin_credential_tokens"
CREATE INDEX "admincredentialtoken_user_id_kind" ON "admin_credential_tokens" ("user_id", "kind");
